<?php $title='Detalhes do módulo'; ?>
<section class="page-head"><div><h1><?= e($project['name']) ?></h1><p><?= e($project['full_name']?:$project['description']) ?></p></div><div><?php if($project['admin_url']): ?><a class="btn primary" href="<?= e($project['admin_url']) ?>" target="_blank" rel="noopener noreferrer">Administrar</a><?php endif; ?> <a class="btn" href="<?= e(base_url('projetos/'.$project['id'].'/editar')) ?>">Editar módulo</a></div></section><?php if($project['status']==='deploying'): ?><div class="alert warning">Módulo em implantação. O endereço administrativo pode ainda estar indisponível; isso não afeta a GDA Plataforma.</div><?php endif; ?><div class="detail-grid"><section class="panel"><h2>Informações do módulo</h2><dl><dt>Nome</dt><dd><?= e($project['name']) ?></dd><dt>Nome completo</dt><dd><?= e($project['full_name']?:'Não informado') ?></dd><dt>Identificador</dt><dd><code><?= e($project['code']) ?></code></dd><dt>Descrição</dt><dd><?= e($project['description']) ?></dd><dt>Categoria</dt><dd><?= e($project['category']?:'Não informada') ?></dd><dt>Versão</dt><dd>v<?= e($project['version']) ?></dd><dt>Status</dt><dd><span class="badge <?= e($project['status']) ?>"><?= e(project_status_label($project['status'])) ?></span></dd><dt>URL pública</dt><dd><?= $project['url']?'<a href="'.e($project['url']).'" target="_blank" rel="noopener noreferrer">'.e($project['url']).'</a>':'Não configurada' ?></dd><dt>URL administrativa</dt><dd><?= e($project['admin_url']?:'Não configurada') ?></dd><dt>Clientes vinculados</dt><dd><?= count($clients) ?></dd></dl></section><section class="panel"><h2>Clientes com acesso</h2><?php if(!$clients): ?><div class="empty">Nenhum cliente vinculado.</div><?php else: ?><div class="project-list"><?php foreach($clients as $c): ?><a href="<?= e(base_url('clientes/'.$c['id'])) ?>"><b><?= e($c['name']) ?></b><small><?= e($c['identifier']) ?></small></a><?php endforeach; ?></div><?php endif; ?></section></div>
<section class="panel"><h2>Integração</h2><?php if(empty($connection)): ?><div class="empty"><b>Projeto ainda não anexado.</b><p>Use uma chave oficial para conectar a instância deste módulo.</p><a class="btn primary" href="<?= e(base_url('projetos/anexar')) ?>">Anexar projeto</a></div><?php else: ?><dl><dt>Estado</dt><dd><?= e(project_connection_status_label($connection['connection_status'])) ?></dd><dt>Instância</dt><dd><code><?= e($connection['module_instance_id']) ?></code></dd><dt>Protocolo</dt><dd>gda-module-attach v<?= (int)$connection['protocol_version'] ?></dd><dt>Capacidades</dt><dd><?= e(project_capabilities_label($connection['capabilities'])) ?></dd><dt>Anexado em</dt><dd><?= e(date('d/m/Y H:i',strtotime($connection['attached_at']))) ?></dd><dt>Última verificação</dt><dd><?= $connection['last_verified_at']?e(date('d/m/Y H:i',strtotime($connection['last_verified_at']))):'Ainda não verificada' ?></dd><dt>URL administrativa</dt><dd><?= e($project['admin_url']?:'Não informada') ?></dd><dt>Anexado por</dt><dd><?= e($connection['attached_by_name']?:'Sistema') ?></dd><dt>Assinatura criptográfica</dt><dd><?= $connection['public_key_fingerprint']?'Identidade registrada':'Disponível futuramente' ?></dd></dl><?php endif; ?></section>
<section class="panel"><h2>Atividade recente</h2><?php if(!$activities): ?><div class="empty">Nenhuma atividade recente deste módulo.</div><?php else: ?><div class="timeline"><?php foreach($activities as $activity): ?><div><span class="dot"></span><p><b><?= e($activity['user_name']??'Sistema') ?></b> — <?= e($activity['description']) ?><small><?= e(date('d/m/Y H:i',strtotime($activity['created_at']))) ?></small></p></div><?php endforeach; ?></div><?php endif; ?></section>
